<section class="panel"><div class="panel-header"><div><h2>Categorias do catálogo</h2><p><?= count($categorias) ?> categoria(s) cadastrada(s).</p></div><a class="btn btn-primary" href="index.php?entidade=categorias&acao=novo">+ Nova categoria</a></div>
<form class="filters" method="get"><input type="hidden" name="entidade" value="categorias"><div class="field grow"><label for="buscar">Pesquisar categoria</label><input id="buscar" name="buscar" type="search" value="<?= e($busca) ?>"></div><button class="btn btn-secondary">Buscar</button></form>
